/* ============================================================
   FILE:      sql/07_agentic/02_agent_service_user.sql
   PURPOSE:   Least-privilege role and service user for the agent backend
   RUN AFTER: sql/07_agentic/01_order_risk_view.sql
   RERUN:     SAFE
   ============================================================ */

USE ROLE ACCOUNTADMIN;

CREATE ROLE IF NOT EXISTS AGENT_ROLE;

GRANT USAGE ON WAREHOUSE SUPPLY_TRUST_WH TO ROLE AGENT_ROLE;
GRANT USAGE ON DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;
GRANT USAGE ON ALL SCHEMAS IN DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;

-- Read-only for now; write access is added per procedure in Step 4
GRANT SELECT ON ALL TABLES IN DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;
GRANT SELECT ON ALL VIEWS  IN DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;
GRANT SELECT ON FUTURE TABLES IN DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;
GRANT SELECT ON FUTURE VIEWS  IN DATABASE SUPPLY_TRUST_DB TO ROLE AGENT_ROLE;

-- Allows AI_COMPLETE
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO ROLE AGENT_ROLE;

CREATE USER IF NOT EXISTS AGENT_SERVICE_USER
    TYPE = SERVICE
    DEFAULT_ROLE = AGENT_ROLE
    DEFAULT_WAREHOUSE = SUPPLY_TRUST_WH
    RSA_PUBLIC_KEY = '';

ALTER USER AGENT_SERVICE_USER
    SET RSA_PUBLIC_KEY = '';

GRANT ROLE AGENT_ROLE TO USER AGENT_SERVICE_USER;
GRANT ROLE AGENT_ROLE TO ROLE ACCOUNTADMIN;   -- lets you test as this role

-- Account identifier for the .env file
SELECT CURRENT_ORGANIZATION_NAME() || '-' || CURRENT_ACCOUNT_NAME() AS ACCOUNT_IDENTIFIER;